From 90a10aeb65d115c268ff9aa0f5ad39a29a1a35b3 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Fr=C3=A9d=C3=A9ric=20L=C3=A9caille?= <flecaille@haproxy.com>
Date: Tue, 14 May 2019 10:57:58 +0200
Subject: [PATCH] BUG/MINOR: log: Wrong log format initialization.

This patch fixes an issue introduced by 0bad840b commit
"MINOR: log: Extract some code to send syslog messages" which leaded
to wrong log format variable initializations at least for "short" and "raw" format.
This commit skipped the cases where even if passed to __do_send_log(), the
syslog tag and syslog pid string must not be used to format the log message
with "short" and "raw". This is done iniatilizing "tag_max" and "pid_max"
variables (the lengths of the tag and pid strings) to 0, then updating to them to
the length of the tag and pid strings passed as variables to __do_send_log()
depending on the log format and in every cases using this length for the iovec
variable used to send() the log.

This bug is specific to 2.0.

diff --git a/src/log.c b/src/log.c
index 7e14d89e2..50553c6fb 100644
--- a/src/log.c
+++ b/src/log.c
@@ -1483,7 +1483,6 @@ static inline void __do_send_log(struct logsrv *logsrv, int nblogger, char *pid_
 	time_t time = date.tv_sec;
 	char *hdr, *hdr_ptr;
 	size_t hdr_size;
-	struct buffer *tag = &global.log_tag;
 	int fac_level;
 	int *plogfd;
 	char *pid_sep1 = "", *pid_sep2 = "";
@@ -1493,6 +1492,7 @@ static inline void __do_send_log(struct logsrv *logsrv, int nblogger, char *pid_
 	int hdr_max = 0;
 	int tag_max = 0;
 	int pid_sep1_max = 0;
+	int pid_max = 0;
 	int pid_sep2_max = 0;
 	int sd_max = 0;
 	int max = 0;
@@ -1605,7 +1605,7 @@ static inline void __do_send_log(struct logsrv *logsrv, int nblogger, char *pid_
 	maxlen = logsrv->maxlen - hdr_max;

 	/* tag */
-	tag_max = tag->data;
+	tag_max = tag_size;
 	if (unlikely(tag_max >= maxlen)) {
 		tag_max = maxlen - 1;
 		sd_max = 0;
@@ -1626,6 +1626,7 @@ static inline void __do_send_log(struct logsrv *logsrv, int nblogger, char *pid_
 	maxlen -= pid_sep1_max;

 	/* pid */
+	pid_max = pid_size;
 	if (unlikely(pid_size >= maxlen)) {
 		pid_size = maxlen - 1;
 		sd_max = 0;
@@ -1656,11 +1657,11 @@ static inline void __do_send_log(struct logsrv *logsrv, int nblogger, char *pid_
 	iovec[0].iov_base = hdr_ptr;
 	iovec[0].iov_len  = hdr_max;
 	iovec[1].iov_base = tag_str;
-	iovec[1].iov_len  = tag_size;
+	iovec[1].iov_len  = tag_max;
 	iovec[2].iov_base = pid_sep1;
 	iovec[2].iov_len  = pid_sep1_max;
 	iovec[3].iov_base = pid_str;
-	iovec[3].iov_len  = pid_size;
+	iovec[3].iov_len  = pid_max;
 	iovec[4].iov_base = pid_sep2;
 	iovec[4].iov_len  = pid_sep2_max;
 	iovec[5].iov_base = sd;
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by incorrect initialization of the log format variables `tag_max` and `pid_max` in the `__do_send_log()` function, which led to the syslog tag and PID string being improperly formatted for "short" and "raw" log formats. This issue arose from a previous commit that did not account for cases where these strings should not be used, resulting in potential log message formatting errors.

        Commit message:
        BUG/MINOR: log: Wrong log format initialization.

This patch fixes an issue introduced by 0bad840b commit
"MINOR: log: Extract some code to send syslog messages" which leaded
to wrong log format variable initializations at least for "short" and "raw" format.
This commit skipped the cases where even if passed to __do_send_log(), the
syslog tag and syslog pid string must not be used to format the log message
with "short" and "raw". This is done iniatilizing "tag_max" and "pid_max"
variables (the lengths of the tag and pid strings) to 0, then updating to them to
the length of the tag and pid strings passed as variables to __do_send_log()
depending on the log format and in every cases using this length for the iovec
variable used to send() the log.

This bug is specific to 2.0.  

        Patch:
          */
 static inline void __do_send_log(struct logsrv *logsrv, int nblogger, char *pid_str, size_t pid_size,
                                  int level, char *message, size_t size, char *sd, size_t sd_size,
                                  char *tag_str, size_t tag_size)
 {
 	static THREAD_LOCAL struct iovec iovec[NB_MSG_IOVEC_ELEMENTS] = { };
 	static THREAD_LOCAL struct msghdr msghdr = {
 		//.msg_iov = iovec,
 		.msg_iovlen = NB_MSG_IOVEC_ELEMENTS
 	};
 	static THREAD_LOCAL int logfdunix = -1;	/* syslog to AF_UNIX socket */
 	static THREAD_LOCAL int logfdinet = -1;	/* syslog to AF_INET socket */
 	static THREAD_LOCAL char *dataptr = NULL;
 	time_t time = date.tv_sec;
 	char *hdr, *hdr_ptr;
 	size_t hdr_size;
-	struct buffer *tag = &global.log_tag;
 	int fac_level;
 	int *plogfd;
 	char *pid_sep1 = "", *pid_sep2 = "";
 	char logheader_short[3];
 	int sent;
 	int maxlen;
 	int hdr_max = 0;
 	int tag_max = 0;
 	int pid_sep1_max = 0;
+	int pid_max = 0;
 	int pid_sep2_max = 0;
 	int sd_max = 0;
 	int max = 0;

 	msghdr.msg_iov = iovec;

 	dataptr = message;

 	if (logsrv->addr.ss_family == AF_UNSPEC) {
 		/* the socket's address is a file descriptor */
 		plogfd = (int *)&((struct sockaddr_in *)&logsrv->addr)->sin_addr.s_addr;
 		if (unlikely(!((struct sockaddr_in *)&logsrv->addr)->sin_port)) {
 			/* FD not yet initialized to non-blocking mode.
 			 * DON'T DO IT ON A TERMINAL!
 			 */
 			if (!isatty(*plogfd))
 				fcntl(*plogfd, F_SETFL, O_NONBLOCK);
 			((struct sockaddr_in *)&logsrv->addr)->sin_port = 1;
 		}
 	}
 	else if (logsrv->addr.ss_family == AF_UNIX)
 		plogfd = &logfdunix;
 	else
 		plogfd = &logfdinet;

 	if (unlikely(*plogfd < 0)) {
 		/* socket not successfully initialized yet */
 		if ((*plogfd = socket(logsrv->addr.ss_family, SOCK_DGRAM,
 							  (logsrv->addr.ss_family == AF_UNIX) ? 0 : IPPROTO_UDP)) < 0) {
 			static char once;

 			if (!once) {
 				once = 1; /* note: no need for atomic ops here */
 				ha_alert("socket() failed in logger #%d: %s (errno=%d)\n",
 						 nblogger, strerror(errno), errno);
 			}
 			return;
 		} else {
 			/* we don't want to receive anything on this socket */
 			setsockopt(*plogfd, SOL_SOCKET, SO_RCVBUF, &zero, sizeof(zero));
 			/* does nothing under Linux, maybe needed for others */
 			shutdown(*plogfd, SHUT_RD);
 			fcntl(*plogfd, F_SETFD, fcntl(*plogfd, F_GETFD, FD_CLOEXEC) | FD_CLOEXEC);
 		}
 	}

 	switch (logsrv->format) {
 	case LOG_FORMAT_RFC3164:
 		hdr = logheader;
 		hdr_ptr = update_log_hdr(time);
 		break;

 	case LOG_FORMAT_RFC5424:
 		hdr = logheader_rfc5424;
 		hdr_ptr = update_log_hdr_rfc5424(time);
 		sd_max = sd_size; /* the SD part allowed only in RFC5424 */
 		break;

 	case LOG_FORMAT_SHORT:
 		/* all fields are known, skip the header generation */
 		hdr = logheader_short;
 		hdr[0] = '<';
 		hdr[1] = '0' + MAX(level, logsrv->minlvl);
 		hdr[2] = '>';
 		hdr_ptr = hdr;
 		hdr_max = 3;
 		maxlen = logsrv->maxlen - hdr_max;
 		max = MIN(size, maxlen) - 1;
 		goto send;

 	case LOG_FORMAT_RAW:
 		/* all fields are known, skip the header generation */
 		hdr_ptr = hdr = "";
 		hdr_max = 0;
 		maxlen = logsrv->maxlen;
 		max = MIN(size, maxlen) - 1;
 		goto send;

 	default:
 		return; /* must never happen */
 	}

 	hdr_size = hdr_ptr - hdr;

 	/* For each target, we may have a different facility.
 	 * We can also have a different log level for each message.
 	 * This induces variations in the message header length.
 	 * Since we don't want to recompute it each time, nor copy it every
 	 * time, we only change the facility in the pre-computed header,
 	 * and we change the pointer to the header accordingly.
 	 */
 	fac_level = (logsrv->facility << 3) + MAX(level, logsrv->minlvl);
 	hdr_ptr = hdr + 3; /* last digit of the log level */
 	do {
 		*hdr_ptr = '0' + fac_level % 10;
 		fac_level /= 10;
 		hdr_ptr--;
 	} while (fac_level && hdr_ptr > hdr);
 	*hdr_ptr = '<';

 	hdr_max = hdr_size - (hdr_ptr - hdr);

 	/* time-based header */
 	if (unlikely(hdr_size >= logsrv->maxlen)) {
 		hdr_max = MIN(hdr_max, logsrv->maxlen) - 1;
 		sd_max = 0;
 		goto send;
 	}

 	maxlen = logsrv->maxlen - hdr_max;

 	/* tag */
-	tag_max = tag->data;
+	tag_max = tag_size;
 	if (unlikely(tag_max >= maxlen)) {
 		tag_max = maxlen - 1;
 		sd_max = 0;
 		goto send;
 	}

 	maxlen -= tag_max;

 	/* first pid separator */
 	pid_sep1_max = log_formats[logsrv->format].pid.sep1.data;
 	if (unlikely(pid_sep1_max >= maxlen)) {
 		pid_sep1_max = maxlen - 1;
 		sd_max = 0;
 		goto send;
 	}

 	pid_sep1 = log_formats[logsrv->format].pid.sep1.area;
 	maxlen -= pid_sep1_max;

 	/* pid */
+	pid_max = pid_size;
 	if (unlikely(pid_size >= maxlen)) {
 		pid_size = maxlen - 1;
 		sd_max = 0;
 		goto send;
 	}

 	maxlen -= pid_size;

 	/* second pid separator */
 	pid_sep2_max = log_formats[logsrv->format].pid.sep2.data;
 	if (unlikely(pid_sep2_max >= maxlen)) {
 		pid_sep2_max = maxlen - 1;
 		sd_max = 0;
 		goto send;
 	}

 	pid_sep2 = log_formats[logsrv->format].pid.sep2.area;
 	maxlen -= pid_sep2_max;

 	/* structured-data */
 	if (sd_max >= maxlen) {
 		sd_max = maxlen - 1;
 		goto send;
 	}

 	max = MIN(size, maxlen - sd_max) - 1;
 send:
 	iovec[0].iov_base = hdr_ptr;
 	iovec[0].iov_len  = hdr_max;
 	iovec[1].iov_base = tag_str;
-	iovec[1].iov_len  = tag_size;
+	iovec[1].iov_len  = tag_max;
 	iovec[2].iov_base = pid_sep1;
 	iovec[2].iov_len  = pid_sep1_max;
 	iovec[3].iov_base = pid_str;
-	iovec[3].iov_len  = pid_size;
+	iovec[3].iov_len  = pid_max;
 	iovec[4].iov_base = pid_sep2;
 	iovec[4].iov_len  = pid_sep2_max;
 	iovec[5].iov_base = sd;
 	iovec[5].iov_len  = sd_max;
 	iovec[6].iov_base = dataptr;
 	iovec[6].iov_len  = max;
 	iovec[7].iov_base = "\n"; /* insert a \n at the end of the message */
 	iovec[7].iov_len  = 1;

 	if (logsrv->addr.ss_family == AF_UNSPEC) {
 		/* the target is a direct file descriptor */
 		sent = writev(*plogfd, iovec, 8);
 	}
 	else {
 		msghdr.msg_name = (struct sockaddr *)&logsrv->addr;
 		msghdr.msg_namelen = get_addr_len(&logsrv->addr);

 		sent = sendmsg(*plogfd, &msghdr, MSG_DONTWAIT | MSG_NOSIGNAL);
 	}

 	if (sent < 0) {
 		static char once;

 		if (errno == EAGAIN)
 			_HA_ATOMIC_ADD(&dropped_logs, 1);
 		else if (!once) {
 			once = 1; /* note: no need for atomic ops here */
 			ha_alert("sendmsg()/writev() failed in logger #%d: %s (errno=%d)\n",
 					 nblogger, strerror(errno), errno);
 		}
 	}
 }



        Provide a response strictly in the following format:
        Code statements:
        <text1>
        <text2>
        ...
        <textN>

Code statements:
```c
int tag_max = 0;
int pid_max = 0;
tag_max = tag_size;
pid_max = pid_size;
iovec[1].iov_len  = tag_max;
iovec[3].iov_len  = pid_max;
```

Code statements:
```c
int tag_max = 0;
int pid_max = 0;
tag_max = tag_size;
pid_max = pid_size;
iovec[1].iov_len  = tag_max;
iovec[3].iov_len  = pid_max;
```
